  "Code that is tested before you get it": "Codice testato prima che ti arrivi",
  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "Il modello scrive il programma e i suoi test, il telefono li esegue e ogni errore torna subito al modello per essere corretto, finché i test non passano. Offline, in una sandbox bloccata.",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "Cosa deve fare? es. “Una funzione che divide il conto del ristorante tra amici, con la mancia”",
  "Web page": "Pagina web",
  "Build & test": "Crea e testa",
  "The program and its tests appear here": "Il programma e i suoi test compaiono qui",
  "Each step, the code, a live preview for web pages, and whether the tests passed.": "Ogni passaggio, il codice, un'anteprima dal vivo per le pagine web e se i test sono passati.",
