  "Keep": "Conserva",
  "filing…": "archiviazione…",
  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "Gratis: conserva e cerca tutto. Pro: archivia ogni elemento da solo (titolo, riassunto, tag), legge le tue foto e risponde alle domande partendo dalla tua Mente.",
