  "PDF · Word · PowerPoint · Excel · CSV · photos · e-books · web pages · subtitles — several photos → one PDF, several PDFs → merged": "PDF · Word · PowerPoint · Excel · CSV · foto · e-book · pagine web · sottotitoli — più foto → un PDF, più PDF → uniti",
