  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Sa come funzionano davvero le cose qui: prezzi giusti, rincari tipici, cosa è scortese. Ti dice quando una cosa richiede dati in tempo reale che offline non può avere.",
