  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "Questo modello è grande per questo telefono. Funziona, ma le risposte arrivano lente e il telefono si scalda. Per risposte rapide e fluide usa Qwen 3.5 4B: stesso arabo, legge le foto, circa 3× più veloce.",
