  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "Tieni tutto su questo telefono e aggiungi chat, memoria, promemoria e giorni del ciclo del backup. Il registro Soldi viene preso dal backup solo se questo telefono non ne ha uno.",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "Le {c} chat e le {l} voci di registro di questo telefono saranno sostituite da quelle del backup. Puoi annullare una sola volta, subito dopo.",
