  "Name the outcome; it fills in the path.": "Indica il risultato: al percorso pensa lui.",
  "Huge window — compress for cost, not for fit.": "Finestra enorme: comprimi per il costo, non per starci.",
  "Direct phrasing; ask for reasoning explicitly.": "Formulazione diretta; chiedi il ragionamento in modo esplicito.",
  "Structured reasoning; keep numbered steps.": "Ragionamento strutturato; mantieni i passaggi numerati.",
  "Strong multilingual — keep the source language.": "Ottimo multilingue: mantieni la lingua di partenza.",
  "Concise by nature; over-compressing loses nuance.": "Conciso per natura; comprimere troppo fa perdere sfumature.",
  "Open weights; explicit instructions beat implied ones.": "Pesi aperti; le istruzioni esplicite valgono più di quelle sottintese.",
  "Long documents are its strength; keep headings.": "Il suo punto di forza sono i documenti lunghi; mantieni i titoli.",
  "Code context competes for the window — trim prose first.": "Il codice compete con la finestra: taglia prima la prosa.",
  "A search tool — keep the sources, cut the styling.": "Un motore di ricerca: tieni le fonti, togli lo stile.",
  "Tight. Cut everything that isn't the instruction.": "Stretta. Taglia tutto ciò che non è l'istruzione.",
