  "Crane mass": "Massa della gru",
  "Heaviest outrigger force": "Forza massima sullo stabilizzatore",
  "Load (with spreader, if any)": "Carico (con bilancino, se presente)",
  "Load mass": "Massa del carico",
  "Load's largest face": "Faccia maggiore del carico",
  "Mat length": "Lunghezza della piastra",
  "Mat width": "Larghezza della piastra",
  "Measured at height": "Misurato all'altezza di",
  "Or the allowable pressure from a site investigation": "Oppure la pressione ammissibile da un'indagine geotecnica",
  "Printed on the load chart (often 9.8 m/s).": "Stampato sulla tabella di carico (spesso 9,8 m/s).",
  "Radius": "Sbraccio",
  "Typical values are the low end of published ranges — a geotechnical figure always wins.": "I valori tipici sono la parte bassa degli intervalli pubblicati: vince sempre un dato geotecnico.",
  "Wind is stronger higher up.": "Il vento è più forte in alto.",
  "Wind now": "Vento ora",
  "Within the chart with margin.": "Entro la tabella con margine.",
  "Critical lift: over {a}% — needs a written lift plan and sign-off.": "Sollevamento critico: oltre il {a}%, serve un piano di sollevamento scritto e firmato.",
  "Over {b}%: too close to the limit — replan (shorter radius, bigger crane, lighter rigging).": "Oltre il {b}%: troppo vicino al limite, ripianifica (sbraccio minore, gru più grande, imbracatura più leggera).",
  "OVER THE CHART — this lift is not allowed.": "OLTRE LA TABELLA: questo sollevamento non è consentito.",
  "m": "m",
  "t": "t",
  "m/s": "m/s",
  "m²": "m²",
  "kN/m²": "kN/m²",
  "%": "%",
  "Planning": "Pianificazione",
  "Text size": "Dimensione del testo",
  "Worked out on the phone — exact, instant, no model": "Calcolato sul telefono: esatto, istantaneo, senza modello",
  "Ask the model": "Chiedi al modello",
  "unusually slow — why?": "insolitamente lento: perché?",
  "Send this report": "Invia questo report",
  "Not available in this build": "Non disponibile in questa versione",
  "The phone is hot — it slows the processor down on purpose. Let it cool, take it out of its case, don't charge while asking.": "Il telefono è caldo e rallenta apposta il processore. Lascialo raffreddare, toglilo dalla custodia, non caricarlo mentre fai domande.",
  "Battery saver is on — it caps the processor. Turn it off while using Attune.": "Il risparmio energetico è attivo e limita il processore. Disattivalo mentre usi Attune.",
  "Free memory is low for this model — close other apps (games, camera, many browser tabs).": "La memoria libera è poca per questo modello: chiudi le altre app (giochi, fotocamera, molte schede del browser).",
  "The model is read from storage instead of RAM — update to the latest Attune APK (it loads the model into RAM).": "Il modello viene letto dall'archiviazione invece che dalla RAM: aggiorna all'ultimo APK di Attune (che lo carica nella RAM).",
  "The engine is using its slowest processor path (no dotprod). Send this report.": "Il motore usa il percorso più lento del processore (senza dotprod). Invia questo report.",
  "The phone is critically hot — Attune stops an answer in progress and keeps what was written. Let it cool for a few minutes.": "Il telefono è critico per il calore: Attune interrompe la risposta in corso e conserva quanto scritto. Lascialo raffreddare qualche minuto.",
  "The phone is very hot — Attune waits up to 20 seconds before each new answer so it can cool, and uses fewer threads the next time the model starts.": "Il telefono è molto caldo: Attune aspetta fino a 20 secondi prima di ogni nuova risposta per farlo raffreddare, e al prossimo avvio del modello usa meno thread.",
  "The phone is getting warm — long answers may slow down soon. Short breaks between answers keep it fast.": "Il telefono si sta scaldando: le risposte lunghe potrebbero presto rallentare. Brevi pause tra una risposta e l'altra lo tengono veloce.",
  "Only {n} threads are used for writing.": "Per scrivere si usano solo {n} thread.",
  "This is a big model for a phone — Qwen 3.5 4B is about 2–3× faster.": "È un modello grande per un telefono: Qwen 3.5 4B è circa 2–3 volte più veloce.",
  "Nothing obvious — the phone may have slowed Attune while it was in the background. The new APK keeps it at full speed while writing.": "Niente di evidente: il telefono potrebbe aver rallentato Attune mentre era in secondo piano. Il nuovo APK lo mantiene a piena velocità mentre scrive.",
  "Nothing is holding it back.": "Niente lo sta frenando.",
  "Money tools": "Strumenti per i soldi",
  "Gemma 4 E2B · fast engine (GPU)": "Gemma 4 E2B · motore veloce (GPU)",
  "Gemma 4 E4B · fast engine (GPU)": "Gemma 4 E4B · motore veloce (GPU)",
  "The fast one. Runs on the phone's graphics chip: the first words appear in under a second and it writes faster than you can read. Reads photos, English and Arabic. For hard reasoning, the E4B below is stronger.": "Quello veloce. Gira sul chip grafico del telefono: le prime parole compaiono in meno di un secondo e scrive più veloce di quanto tu legga. Legge foto, inglese e arabo. Per ragionamenti difficili, l'E4B qui sotto è più forte.",
  "The stronger fast one: noticeably better answers than the E2B, still on the graphics chip — first words in about a second, then roughly 20–45 words a second on a flagship.": "Il veloce più forte: risposte nettamente migliori dell'E2B, sempre sul chip grafico: prime parole in circa un secondo, poi circa 20–45 parole al secondo su un modello di punta.",
  "Stronger ·": "Più forte ·",
  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick answers use Gemma 4 E2B on the fast engine — reads photos, first words in about a second.": "Questo modello è grande per questo telefono. Funziona, ma le risposte arrivano lente e il telefono si scalda. Per risposte rapide usa Gemma 4 E2B sul motore veloce: legge foto, prime parole in circa un secondo.",
  "Fast engine on the graphics chip": "Motore veloce sul chip grafico",
  "Fast engine on the CPU": "Motore veloce sulla CPU",
  "multi-token prediction on": "previsione multi-token attiva",
  "Use the graphics chip": "Usa il chip grafico",
  "On: the model runs on the GPU — first words in about a second. Off: the CPU, slower, only for phones whose GPU driver misbehaves.": "Attivo: il modello gira sulla GPU, prime parole in circa un secondo. Disattivo: la CPU, più lenta, solo per telefoni il cui driver GPU dà problemi.",
  "Gemma 4 E2B on the graphics chip: first words in about a second, many times faster than this engine. {s} GB, once.": "Gemma 4 E2B sul chip grafico: prime parole in circa un secondo, molte volte più veloce di questo motore. {s} GB, una sola volta.",
  "The fast engine is running on the CPU, not the graphics chip — turn on “Use the graphics chip” above. If it switched itself off, the phone's GPU driver refused it: send this report.": "Il motore veloce gira sulla CPU, non sul chip grafico: attiva «Usa il chip grafico» qui sopra. Se si è disattivato da solo, il driver GPU del telefono l'ha rifiutato: invia questo report.",
  "The biggest speed-up on this phone is the fast engine: Gemma 4 E2B on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "Il maggior aumento di velocità su questo telefono è il motore veloce: Gemma 4 E2B sul chip grafico, prime parole in circa un secondo. Tocca «Passa al motore veloce» qui sopra.",
  "The GPU would not start, so the fast engine is on the CPU. ": "La GPU non è partita, quindi il motore veloce gira sulla CPU. ",
  "Last time, starting the fast engine on the GPU closed the app. It is on the CPU now; you can try the GPU again in Engine → Speed.": "L'ultima volta, l'avvio del motore veloce sulla GPU ha chiuso l'app. Ora è sulla CPU; puoi riprovare la GPU in Motore → Velocità.",
  "Preparing the fast engine (the first start on the GPU takes longest)": "Preparazione del motore veloce (il primo avvio sulla GPU è il più lungo)",
  "Change it… e.g. “also show the total in EGP”": "Cambialo… es. «mostra anche il totale in EGP»",
  "Changed {n} place(s) in the code.": "Modificati {n} punti nel codice.",
