  "What are the key points?": "Quali sono i punti chiave?",
  "Checklist: what every answer must satisfy (one per line, optional)": "Lista di controllo: cosa deve soddisfare ogni risposta (una per riga, facoltativa)",
  "Facts the AI should know (prices, rules, terms — optional)": "Fatti che l'IA dovrebbe conoscere (prezzi, regole, termini; facoltativo)",
  "Separate topics with an empty line. Only the paragraphs that fit the question are used, so this can be long.": "Separa gli argomenti con una riga vuota. Vengono usati solo i paragrafi pertinenti alla domanda, quindi può essere lungo.",
  "Facts": "Fatti",
  "It also runs this small program on your phone (offline, in a locked box — no internet, no files, no access to the app)": "Esegue anche questo piccolo programma sul tuo telefono (offline, in una scatola chiusa: niente internet, niente file, nessun accesso all'app)",
  "Edit or improve my CV": "Modifica o migliora il mio CV",
  "Say what to add or change («add my job at Dar Al Fouad Hospital as a nurse, 2019–2022», «change my phone to …»), or leave it empty and just make it more professional. You see the result before it is kept.": "Di' cosa aggiungere o cambiare («aggiungi il mio lavoro all'ospedale Dar Al Fouad come infermiere, 2019–2022», «cambia il mio telefono in …»), oppure lascia vuoto e rendilo solo più professionale. Vedi il risultato prima che venga conservato.",
  "What should be added or changed? (optional)": "Cosa va aggiunto o cambiato? (facoltativo)",
  "Apply my change": "Applica la mia modifica",
  "Change + make it professional": "Modifica + rendilo professionale",
  "New version": "Nuova versione",
  "Use this version": "Usa questa versione",
  "Done — you can undo it": "Fatto: puoi annullare",
  "Undo the last change": "Annulla l'ultima modifica",
  "Stuck — starting again from scratch with a different approach": "Bloccato: si ricomincia da capo con un approccio diverso",
  "Wrote it, with {n} tests.": "Scritto, con {n} test.",
  "Your programs": "I tuoi programmi",
  "not passing": "non superato",
  "passing": "superato",
  "✓ Passed all {n} tests.": "✓ Superati tutti i {n} test.",
  "✓ Ran without errors.": "✓ Eseguito senza errori.",
  "The fix did not match the code.": "La correzione non corrispondeva al codice.",
  "The model answered without code.": "Il modello ha risposto senza codice.",
  "The fix deleted the tests — refused.": "La correzione ha eliminato i test: rifiutata.",
  "The model answered without any code — try asking again in other words.": "Il modello ha risposto senza alcun codice: prova a chiedere di nuovo con altre parole.",
  "A picture — Studio draws it on this phone": "Un'immagine: Studio la disegna su questo telefono",
  "Another version": "Un'altra versione",
  "Could not open that picture": "Impossibile aprire quell'immagine",
  "Could not save": "Impossibile salvare",
  "Current photo quality in 4 steps: people, places, products and text in pictures. Also edits a photo you give it (“make it night”, “remove the car”).": "Qualità fotografica attuale in 4 passaggi: persone, luoghi, prodotti e testo nelle immagini. Modifica anche una foto che gli dai («fai notte», «togli l'auto»).",
  "Describe the picture, in Arabic or English — e.g. “a felucca on the Nile at sunset”": "Descrivi l'immagine, in arabo o inglese, es. «una feluca sul Nilo al tramonto»",
  "Developing the picture…": "Sviluppo dell'immagine…",
  "Download it on Wi-Fi. After that, pictures are made with no internet at all.": "Scaricalo con il Wi-Fi. Poi le immagini si creano senza alcuna connessione a internet.",
  "Draw it": "Disegnala",
  "Draw it in Studio": "Disegnala in Studio",
  "A place — Maps finds it": "Un luogo: lo trova Mappe",
  "Show on the map": "Mostra sulla mappa",
  "Draw on the graphics chip (faster; switches itself off if the driver fails)": "Disegna sul chip grafico (più veloce; si disattiva da solo se il driver fallisce)",
  "Drawing on the GPU failed, so Attune switched Studio to the CPU. ": "Il disegno sulla GPU non è riuscito, quindi Attune ha portato Studio sulla CPU. ",
  "Drawing — step {n} of {t}": "Disegno: passo {n} di {t}",
  "Each picture is made by a separate engine process: when it finishes, all its memory goes back to the phone. Nothing is uploaded.": "Ogni immagine è creata da un processo del motore separato: quando finisce, tutta la sua memoria torna al telefono. Non viene caricato nulla.",
  "Edit a photo": "Modifica una foto",
  "Edit it": "Modificala",
  "Edit this": "Modifica questa",
  "GB, once": "GB, una sola volta",
  "Install the picture model first (Studio).": "Prima installa il modello per le immagini (Studio).",
  "Install the sharpening model first (Studio).": "Prima installa il modello di nitidezza (Studio).",
  "Install · {s} GB": "Installa · {s} GB",
  "Landscape": "Orizzontale",
  "Loading the picture model…": "Caricamento del modello per le immagini…",
  "Loading the picture model… {p}%": "Caricamento del modello per le immagini… {p}%",
  "Makes a finished picture four times bigger and sharper — for printing or zooming in.": "Rende un'immagine finita quattro volte più grande e nitida: per stampare o ingrandire.",
  "Pick a photo": "Scegli una foto",
