  "Portrait": "Verticale",
  "Quick draft": "Bozza rapida",
  "Reading your description…": "Lettura della tua descrizione…",
  "Save to gallery": "Salva nella galleria",
  "Saved to {w}": "Salvato in {w}",
  "Saving to the gallery needs Android 10 or newer — use Share instead.": "Salvare nella galleria richiede Android 10 o successivo: usa Condividi.",
  "Saving…": "Salvataggio…",
  "Sharpening ×4": "Nitidezza ×4",
  "Sharpening ×4 — part {n} of {t}": "Nitidezza ×4: parte {n} di {t}",
  "Square": "Quadrato",
  "Starting the download…": "Avvio del download…",
  "Starting the picture engine…": "Avvio del motore delle immagini…",
  "Studio works in the Android app.": "Studio funziona nell'app Android.",
  "The chat model was paused to make room, and is loading again.": "Il modello della chat è stato messo in pausa per fare spazio e si sta ricaricando.",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "Questo APK non ha ancora il motore per le immagini: arriverà con il prossimo APK compilato su GitHub.",
  "This build draws on the CPU.": "Questa versione disegna sulla CPU.",
  "This build of the app has no picture engine yet.": "Questa versione dell'app non ha ancora il motore per le immagini.",
  "This phone has {n} GB — it may be too little for pictures.": "Questo telefono ha {n} GB: potrebbero essere pochi per le immagini.",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Questa versione di Attune non ha il motore immagini per il chip grafico, quindi le immagini vengono disegnate sulla CPU (più lento). Un aggiornamento lo aggiunge.",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "Il motore delle immagini ha smesso di rispondere durante il caricamento del modello ed è stato fermato. Motore → Log del motore mostra le sue ultime righe: invialo all'assistenza.",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "Il driver GPU di questo telefono non ha risposto, quindi le immagini vengono disegnate sulla CPU (più lento).",
  "What should change? e.g. “make it night, with the street lights on”": "Cosa deve cambiare? es. «fai notte, con i lampioni accesi»",
  "Write a fuller description first (better pictures; uses the chat model)": "Scrivi prima una descrizione più completa (immagini migliori; usa il modello della chat)",
  "Writing a fuller description…": "Scrittura di una descrizione più completa…",
  "needs {n} GB RAM": "richiede {n} GB di RAM",
  "{m} is ready": "{m} è pronto",
  "×4 sharper": "×4 più nitida",
  "drawn on the {b} in {t}": "disegnata sul {b} in {t}",
  "sharpened on the {b} in {t}": "resa nitida sul {b} in {t}",
  "Newest": "Più recenti",
  "stopped a repeat": "ripetizione fermata",
  "Checked by running code on this phone": "Verificato eseguendo codice su questo telefono",
  "It printed:": "Ha stampato:",
  "fixed {n}×": "corretto {n}×",
  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "Non sono ancora riuscito a far passare tutti i test: ecco la versione più vicina; tocca «Prova e correggi in Codice» per continuare.",
  "Working it out as a program…": "Lo risolvo con un programma…",
  "Fixing the program and running it again…": "Correggo il programma e lo eseguo di nuovo…",
  "Checked by running code — writing the answer…": "Verificato eseguendo il codice: scrittura della risposta…",
  "Looking at the photo…": "Guardo la foto…",
  "Searching the web…": "Ricerca sul web…",
  "FLUX.2 klein 4B · high quality": "FLUX.2 klein 4B · alta qualità",
  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "Le migliori immagini che questo telefono può creare: la versione a 8 bit di FLUX.2 klein, con dettagli più fini, volti, mani e testo più puliti. Modifica anche le tue foto da un'istruzione.",
  "That file is too large (15 MB at most)": "Il file è troppo grande (massimo 15 MB)",
  "What's in this file? Summarise what matters.": "Cosa c'è in questo file? Riassumi ciò che conta.",
  "Checked — the reviewer fixed a mistake": "Verificato: il revisore ha corretto un errore",
