  "Wrong? Teach the right answer": "Sbagliato? Insegna la risposta giusta",
  "What should it have said? Chat will answer this way next time you ask something like it.": "Cosa avrebbe dovuto dire? La prossima volta che chiederai qualcosa di simile, la Chat risponderà così.",
  "The right answer": "La risposta giusta",
  "Why (optional) — e.g. “the marble falls out when the glass is turned over”": "Perché (facoltativo), es. «la biglia cade quando il bicchiere si capovolge»",
  "Learned — Chat will use this on similar questions": "Imparato: la Chat lo userà su domande simili",
