  "What should it have said? Attune double-checks your correction first, and learns it only if it holds up.": "Cosa avrebbe dovuto dire? Attune ricontrolla prima la tua correzione e la impara solo se regge.",
  "Checked — I don't think the correction is right": "Verificato: non credo che la correzione sia giusta",
