  "Edit my correction": "Modifica la mia correzione",
  "Checking…": "Verifica…",
  "Check & teach": "Verifica e insegna",
  "Double-checking your correction…": "Ricontrollo la tua correzione…",
  "Checking your correction by computing it…": "Verifico la tua correzione calcolandola…",
  "The checks disagree — one more look…": "I controlli non concordano: un'altra occhiata…",
  "Checked — you're right. Learned for next time": "Verificato: hai ragione. Imparato per la prossima volta",
