  "Change the design in words — add fields to any table, new tables, links…": "Cambia il progetto a parole: aggiungi campi a qualsiasi tabella, nuove tabelle, collegamenti…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "es. aggiungi Email e Partita IVA a Fornitori, e un campo Mesi di garanzia a Ricambi",
  "Saved — send this file; it opens in any browser, no Attune needed": "Salvato: invia questo file; si apre in qualsiasi browser, senza bisogno di Attune",
  "Excel files need Python, which isn't in this build — use CSV.": "I file Excel richiedono Python, che non è in questa versione: usa il CSV.",
  "Making the Excel file…": "Creazione del file Excel…",
  "Couldn't make the Excel file: {e}": "Impossibile creare il file Excel: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "Consegnalo al tuo team come app: un unico file con tutti i dati dentro, che si apre nel browser di qualsiasi telefono o computer, senza bisogno di Attune. Quando serve cambiare qualcosa, apri qui il file (Lavoro → Apri un file app), chiedi all'IA e rimanda indietro la nuova app.",
  "Export as an app": "Esporta come app",
  "Excel workbook (all tables)": "Cartella di lavoro Excel (tutte le tabelle)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "Il motore delle immagini si è fermato prima di finire l'immagine: forse Android l'ha chiuso per liberare memoria. Prova «Bozza rapida», oppure chiudi le altre app e riprova.",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "Non è stato possibile creare l'immagine. Apri Motore → Log del motore e mandami ciò che dice.",
  "Multi-token prediction (faster writing)": "Previsione multi-token (scrittura più veloce)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "Disattivata di default: su alcuni telefoni raddoppia parole e cifre («ItIt is is», «20205»). Attivala solo se le risposte restano corrette.",
  "The last picture didn't finish:": "L'ultima immagine non è stata completata:",
