  "Studio Turbo": "Studio Turbo",
  "Studio Pro": "Studio Pro",
  "Studio Pro HD": "Studio Pro HD",
  "Turbo · about 1 min": "Turbo · circa 1 min",
  "Studio Turbo+": "Studio Turbo+",
  "Recommended for your phone": "Consigliato per il tuo telefono",
  "Studio Ultra": "Studio Ultra",
  "Ultra · best quality, slow · {s} GB": "Ultra · qualità migliore, lento · {s} GB",
  "best quality, slow": "qualità migliore, lento",
  "fastest pictures": "immagini più veloci",
  "a graphics card with 8 GB or more: the most capable model": "una scheda grafica da 8 GB o più: il modello più capace",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "Il modello più capace: testo dentro le immagini, scene affollate, persone. Lento su un telefono (circa 10 minuti a immagine), veloce su un computer con scheda grafica. Richiede 12 GB di RAM.",
  "about {s} s a picture": "circa {s} s a immagine",
  "8 GB or more and fast cores: the sharper XL model in one step": "8 GB o più e core veloci: il modello XL più nitido in un solo passaggio",
  "not enough free storage or speed for the XL model": "spazio libero o velocità insufficienti per il modello XL",
  "the fast model fits this phone's memory": "il modello veloce sta nella memoria di questo telefono",
  "little memory or slow cores: smaller pictures, still clear": "poca memoria o core lenti: immagini più piccole, comunque chiare",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · circa 20 s · {s} GB",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Più veloce e nitido di Turbo, con una migliore aderenza a ciò che chiedi: circa 20 secondi a immagine sulla CPU. 512 px. Per telefoni con 8 GB di RAM o più.",
  "Pro · best quality": "Pro · qualità migliore",
  "Pro on this phone's CPU: 10–20 min a picture": "Pro sulla CPU di questo telefono: 10–20 min a immagine",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "Il chip grafico di questo telefono non funziona con Studio, quindi il modello Pro impiegherebbe 10–20 minuti a immagine sulla CPU. Studio Turbo crea un'immagine in circa un minuto.",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "Immagini veloci su qualsiasi telefono: circa un minuto senza chip grafico, secondi con uno. 512 px: ottimo per idee, bozze e post.",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "La migliore qualità fotografica: persone, luoghi, prodotti e testo nelle immagini, 1024 px. Modifica anche una foto che gli dai («fai notte», «togli l'auto»). Richiede un chip grafico funzionante: sulla CPU un'immagine richiede 10–20 minuti.",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "Studio Pro a piena precisione: dettagli più fini, volti, mani e testo più puliti. Modifica anche le tue foto da un'istruzione. Richiede un chip grafico funzionante e 12 GB di RAM.",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "Ancora al lavoro: niente è bloccato. Turbo impiega circa 1–2 minuti sulla CPU. Tieni Attune aperto; Stop la annulla.",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "Ancora al lavoro: niente è bloccato. Senza chip grafico un'immagine Pro richiede 10–20 minuti (le modifiche di più). Per la velocità, scegli Turbo. Tieni Attune aperto; Stop la annulla.",
  "Delete this chat?": "Eliminare questa chat?",
  "This can't be undone.": "Non si può annullare.",
  "Delete this reminder?": "Eliminare questo promemoria?",
  "Delete this project?": "Eliminare questo progetto?",
  "Remove this crane from the fleet?": "Rimuovere questa gru dalla flotta?",
  "Remove this from the project?": "Rimuoverlo dal progetto?",
