  "Spark (helper)": "Spark (aiutante)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "Funziona solo con Spark, Glow, Core e Zenith, non con il modello in uso.",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "Scarica Spark come aiutante (circa 0,5 GB, una sola volta). Funziona con Glow, Core e Zenith.",
  "This is a big model for a phone — Core is about 2–3× faster.": "È un modello grande per un telefono: Core è circa 2–3 volte più veloce.",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "Il modello più potente che un telefono da 12 GB possa eseguire: risposte da esperto, il migliore nel leggere documenti e foto.",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "Core ridotto del 10% per un telefono da 4 GB: vale più di Glow.",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "Gira su un telefono economico e legge comunque le foto. Buone risposte brevi; sui ragionamenti lunghi si nota la dimensione.",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "Per un telefono che non regge altro: sistemare e accorciare testi. Non per ragionare.",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "Il maggior aumento di velocità su questo telefono è il motore veloce: Blaze sul chip grafico, prime parole in circa un secondo. Tocca «Passa al motore veloce» qui sopra.",
