  "Studio is drawing on the processor (slow). This phone has a graphics chip — try it: pictures and ×4 sharpening are many times faster there.": "Studio sta disegnando sul processore (lento). Questo telefono ha un chip grafico: provalo, immagini e nitidezza ×4 sono molte volte più veloci.",
  "The next picture uses the graphics chip": "La prossima immagine usa il chip grafico",
  "This picture was drawn on the CPU because the graphics chip didn't finish; the next picture tries the graphics chip again.": "Questa immagine è stata disegnata sulla CPU perché il chip grafico non ha finito; la prossima prova di nuovo con il chip grafico.",
  "Drawing on the GPU failed twice, so Attune switched Studio to the CPU. ": "Il disegno sulla GPU è fallito due volte, quindi Attune ha portato Studio sulla CPU. ",
  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "Il driver GPU si è bloccato due volte durante il caricamento del modello immagini, quindi Attune ha portato Studio sulla CPU (puoi riprovare la GPU qui sotto).",
  "Show only the models worth using on this device": "Mostra solo i modelli utili su questo dispositivo",
  "Combine your data": "Unisci i tuoi dati",
  "{t} › {f} holds {to} names ({m} of {n} found).": "{t} › {f} contiene {to} nomi ({m} su {n} trovati).",
  "Not in {to} yet: {x}": "Non ancora in {to}: {x}",
