  "Download a whole country once: every road, building, place and shop, and search — all with no signal. A new version is built every week from OpenStreetMap; the app tells you when one is ready.": "Scarica un intero paese una volta sola: ogni strada, edificio, luogo e negozio, con la ricerca, tutto senza segnale. Ogni settimana viene creata una nuova versione da OpenStreetMap; l'app ti avvisa quando è pronta.",
