  "Download the whole map of {c}? {s} — on Wi-Fi is best. Every road, building, place and shop, and offline search.": "Scaricare l'intera mappa di {c}? {s}: meglio con il Wi-Fi. Ogni strada, edificio, luogo e negozio, e la ricerca offline.",
