  "Ask the airline for the reason: weather or an air-traffic strike would cancel it; a technical fault or crew shortage would not.": "Chiedi alla compagnia il motivo: maltempo o sciopero del controllo del traffico aereo lo annullerebbero; un guasto tecnico o la mancanza di equipaggio no.",
  "Write the claim": "Scrivi il reclamo",
  "No compensation": "Nessun risarcimento",
