  "Which airline was it? (Canada's amounts depend on its size)": "Quale compagnia era? (Gli importi del Canada dipendono dalle sue dimensioni)",
  "How late did you arrive at your destination (hours)?": "Con quante ore di ritardo sei arrivato a destinazione?",
  "Over 3,500 km with a 3–4 hour delay: the airline may halve it.": "Oltre 3.500 km con un ritardo di 3–4 ore: la compagnia può dimezzarlo.",
  "Told 7–13 days ahead: not owed if they offered a flight leaving at most 2 h earlier and arriving at most 4 h later than yours.": "Avvisato 7–13 giorni prima: non ti spetta se ti hanno offerto un volo in partenza al massimo 2 h prima e in arrivo al massimo 4 h dopo il tuo.",
  "Told under 7 days ahead: not owed only if they offered a flight leaving at most 1 h earlier and arriving at most 2 h later than yours.": "Avvisato meno di 7 giorni prima: non ti spetta solo se ti hanno offerto un volo in partenza al massimo 1 h prima e in arrivo al massimo 2 h dopo il tuo.",
  "Owed when the delay was within the airline's control and not for safety. Claim within 1 year.": "Ti spetta se il ritardo dipendeva dalla compagnia e non da motivi di sicurezza. Fai reclamo entro 1 anno.",
