  "Running on the NPU ({d}).": "In esecuzione sull'NPU ({d}).",
  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "Esegue il modello sull'NPU Snapdragon (Hexagon): molto più fresco, spesso più veloce a leggere. Funziona meglio con Core Max (8-bit). Torna da solo alla CPU se qualcosa va storto.",
