  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "L'ultima volta, l'avvio sull'NPU ha chiuso l'app. Attune è tornato sulla CPU; puoi riprovare in Motore → Velocità.",
  "You have {b}. Until {d} ({n} days) these are due: {t}. What is left, shared over the days, is what you can spend each day.": "Hai {b}. Fino al {d} ({n} giorni) scadono: {t}. Ciò che resta, diviso per i giorni, è quanto puoi spendere ogni giorno.",
