  "Needed from now: {x} a month": "Necessario da ora: {x} al mese",
  "Mission started — Attune works on it every day": "Missione avviata — Attune ci lavora ogni giorno",
  "Say a goal with a deadline. Attune works on it every day: it reads your money, food and Scout ads, gives your real chance, and the one step for today.": "Di' un obiettivo con una scadenza. Attune ci lavora ogni giorno: legge i tuoi soldi, il cibo e gli annunci di Scout, ti dà la tua vera probabilità e il passo da fare oggi.",
  "e.g. «عايز أوفر 60 ألف قبل يونيو»": "es. «عايز أوفر 60 ألف قبل يونيو»",
  "Save {t}": "Risparmia {t}",
  "Lose {t} kg": "Perdi {t} kg",
  "Buy it for {t} or less": "Compralo a {t} o meno",
  "by {d}": "entro il {d}",
  "add a date (e.g. by June)": "aggiungi una data (es. entro giugno)",
  "Say a number and a date: save 60,000 by June · lose 6 kg before 20 January · buy … under 900k by 1 December · spend no more than 3,000 on food this month · pay off Ahmed's debt by December · finish the Turkish course by December.": "Di' un numero e una data: risparmiare 60.000 entro giugno · perdere 6 kg prima del 20 gennaio · comprare … sotto 900k entro il 1° dicembre · non spendere più di 3.000 in cibo questo mese · saldare il debito di Ahmed entro dicembre · finire il corso di turco entro dicembre.",
  "Start the mission": "Avvia la missione",
  "Your money missions need {a} a month together, but you keep about {b}. Pause one, or move a date.": "Le tue missioni sui soldi richiedono insieme {a} al mese, ma tu metti da parte circa {b}. Mettine in pausa una o sposta una data.",
  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "Nessuna missione ancora. Avviane una qui sopra — un obiettivo di risparmio, di peso, qualcosa da comprare, un limite di spesa, un debito o un corso.",
  "A goal with a date — Attune works on it every day": "Un obiettivo con una data — Attune ci lavora ogni giorno",
  "{c}% chance": "{c}% di probabilità",
  "A goal with a date — Attune works on it every day and shows your real chance": "Un obiettivo con una data — Attune ci lavora ogni giorno e mostra la tua vera probabilità",
  "Where": "Dove",
  "Every tool in three steps, with a drawing of its screen — and a plan to make Attune part of your day.": "Ogni strumento in tre passi, con un disegno della sua schermata — e un piano per rendere Attune parte della tua giornata.",
  "Sync": "Sincronizza",
  "Backup & sync": "Backup e sincronizzazione",
  "Synced — {a} new, {c} updated. Reopening…": "Sincronizzato — {a} nuovi, {c} aggiornati. Riapro…",
  "Waiting for the other device…": "In attesa dell'altro dispositivo…",
  "Merging…": "Unisco…",
  "Locking and sending…": "Cifro e invio…",
  "Signing in to Google…": "Accesso a Google…",
  "Locking and uploading…": "Cifro e carico…",
  "Type the address shown on the other device, like 192.168.1.20:41873": "Scrivi l'indirizzo mostrato sull'altro dispositivo, come 192.168.1.20:41873",
  "The code has 8 letters and numbers": "Il codice ha 8 lettere e numeri",
  "Set your sync passphrase first — the same on every device.": "Imposta prima la passphrase di sincronizzazione — la stessa su ogni dispositivo.",
  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "Mantieni uguali il telefono e il computer (o due telefoni). I dati vengono cifrati prima di lasciare questo dispositivo; ciò che elimini su uno viene eliminato sull'altro, nient'altro va perso.",
  "Wi-Fi": "Wi-Fi",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "Consenti ad Attune di trovare l'altro dispositivo su questa rete Wi-Fi (Android lo chiede una volta).",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "Sull'altro dispositivo: Backup → Sincronizza → Wi-Fi → Connetti, e scrivi:",
  "not on Wi-Fi": "non connesso al Wi-Fi",
  "Show a code on this device": "Mostra un codice su questo dispositivo",
  "Or connect to the other device": "Oppure connettiti all'altro dispositivo",
  "Make this device exactly like the other one (removes what the other doesn't have)": "Rendi questo dispositivo identico all'altro (rimuove ciò che l'altro non ha)",
  "Connect and sync": "Connetti e sincronizza",
  "One file in your own Google Drive, in a hidden folder only Attune can open. It is locked with your sync passphrase on this device, so Google only stores noise.": "Un file nel tuo Google Drive, in una cartella nascosta che solo Attune può aprire. È cifrato con la tua passphrase di sincronizzazione su questo dispositivo, quindi Google conserva solo rumore.",
  "Sync passphrase set on this device.": "Passphrase di sincronizzazione impostata su questo dispositivo.",
  "Sync passphrase (10+ characters, the same on every device)": "Passphrase di sincronizzazione (10+ caratteri, la stessa su ogni dispositivo)",
  "Save passphrase": "Salva la passphrase",
  "Sync with Google Drive": "Sincronizza con Google Drive",
  "Last synced: {d}": "Ultima sincronizzazione: {d}",
  "Wrong code or passphrase — nothing was changed.": "Codice o passphrase errati — non è stato cambiato nulla.",
  "Use at least 10 characters — the file lives in your Drive, so the passphrase is its only lock.": "Usa almeno 10 caratteri — il file sta nel tuo Drive, quindi la passphrase è il suo unico lucchetto.",
  "That passphrase is too easy to guess.": "Quella passphrase è troppo facile da indovinare.",
  "Only available in the Attune app": "Disponibile solo nell'app Attune",
  "Google sync on the computer comes in the next update — use Wi-Fi with your phone for now.": "La sincronizzazione Google sul computer arriva con il prossimo aggiornamento — per ora usa il Wi-Fi con il telefono.",
