  "Copied as it is, no re-encoding: quick and cool. The part starts at the nearest key frame, so it may begin a second early.": "Copiato così com'è, senza ricodifica: veloce e senza scaldare. La parte inizia dal fotogramma chiave più vicino, quindi può partire un secondo prima.",
