  "Connections: {n} · places: {p} · blocked: {b}. Each place and why is below.": "Connessioni: {n} · destinazioni: {p} · bloccate: {b}. Ogni destinazione e il motivo sono qui sotto.",
  "No connections at all — Attune worked fully offline.": "Nessuna connessione — Attune ha funzionato del tutto offline.",
  "The AI ran on this device: none of your chats, notes, photos or money went to an AI company.": "L'AI è stata eseguita su questo dispositivo: nessuna delle tue chat, note, foto o dei tuoi soldi è andata a un'azienda di AI.",
  "{n} times": "{n} volte",
  "{n} blocked": "{n} bloccate",
  "Only the place and the reason are kept, never what was sent. Counted on this device; it starts from the day you installed this update.": "Vengono conservati solo la destinazione e il motivo, mai ciò che è stato inviato. Contato su questo dispositivo; parte dal giorno in cui hai installato questo aggiornamento.",
