  "Android will ask to add it to your home screen": "Android chiederà di aggiungerla alla schermata Home",
  "This phone's home screen can't add it — open it from Artifacts": "La schermata Home di questo telefono non può aggiungerla — aprila da Artifacts",
  "Home screen": "Schermata Home",
  "Clear data": "Cancella dati",
  "Recall": "Ricordi",
  "Find anything on your phone by meaning — screenshots, notifications, chats, notes": "Trova qualsiasi cosa sul telefono per significato — screenshot, notifiche, chat, note",
  "Reading {a} of {b}…": "Leggo {a} di {b}…",
  "{n} added — text read in {k}": "{n} aggiunti — testo letto in {k}",
  "Turn on Notification access for Attune, then come back": "Attiva l'Accesso alle notifiche per Attune, poi torna qui",
  "Kept notifications forgotten": "Notifiche conservate dimenticate",
  "Find anything… e.g. the wifi password from a screenshot, the address Ahmed sent": "Trova qualsiasi cosa… es. la password del wifi da uno screenshot, l'indirizzo che ha mandato Ahmed",
  "Looking in": "Cerco in",
  "Nothing found — try other words, or fewer": "Nessun risultato — prova altre parole, o meno parole",
  "Android said no — you can allow SMS for Attune in App info.": "Android ha detto di no — puoi consentire gli SMS per Attune in Info app.",
  "{n} bank messages from the last year are waiting below for you to check.": "{n} messaggi della banca dell'ultimo anno ti aspettano qui sotto da controllare.",
  "Bring in your old bank SMS": "Importa i vecchi SMS della banca",
  "Money starts with the last 12 months instead of today. Only bank and wallet messages; never one-time codes; nothing leaves the phone.": "Soldi parte dagli ultimi 12 mesi invece che da oggi. Solo messaggi di banche e portafogli; mai codici monouso; niente lascia il telefono.",
  "Read my bank SMS": "Leggi i miei SMS della banca",
  "{n} emails about money read — {p} payments are waiting in Money for a tap.": "{n} email sui soldi lette — {p} pagamenti ti aspettano in Soldi per un tocco.",
  "Gmail is connected": "Gmail è collegato",
  "Read my Gmail by itself": "Leggi Gmail da solo",
  "Once a day Attune reads the new emails about money — receipts, bank alerts, subscriptions, price changes. Last read: {t}. {n} kept for Recall.": "Una volta al giorno Attune legge le nuove email sui soldi — ricevute, avvisi della banca, abbonamenti, cambi di prezzo. Ultima lettura: {t}. {n} conservate per Ricordi.",
  "Receipts, bank alerts, subscriptions and price changes go to Money, the Overpaying check and Recall. Read on this phone; never one-time codes. Google asks you once.": "Ricevute, avvisi della banca, abbonamenti e cambi di prezzo vanno in Soldi, in Paghi troppo? e in Ricordi. Letti su questo telefono; mai codici monouso. Google te lo chiede una volta.",
  "Connect Gmail": "Collega Gmail",
  "Disconnect": "Scollega",
  "{n} payments from Gmail are waiting in Money": "{n} pagamenti da Gmail ti aspettano in Soldi",
  "Gmail isn't connected yet": "Gmail non è ancora collegato",
  "Gmail sign-in was cancelled": "Accesso a Gmail annullato",
  "Google asks you to confirm again — tap Read now.": "Google ti chiede di confermare di nuovo — tocca Leggi ora.",
  "Attune only reads emails about money, on this phone. They never go to Attune, to an AI in the cloud or to anyone else, and are never used for ads. Disconnect any time.": "Attune legge solo le email sui soldi, su questo telefono. Non vanno mai ad Attune, a un'AI nel cloud o a nessun altro, e non vengono mai usate per la pubblicità. Scollega quando vuoi.",
  "Who should it go to? Add an email address.": "A chi va inviata? Aggiungi un indirizzo email.",
  "You can still use Open in Gmail.": "Puoi comunque usare Apri in Gmail.",
  "Sent from your Gmail to {to}.": "Inviata dal tuo Gmail a {to}.",
  "Your email — check it, then send": "La tua email — controllala, poi inviala",
  "{n}'s email address": "Indirizzo email di {n}",
  "Not an email address: {a}": "Non è un indirizzo email: {a}",
  "Subject": "Oggetto",
  "Writing it…": "La scrivo…",
  "Open in Gmail": "Apri in Gmail",
  "Nothing is sent until you tap Send — here or in Gmail.": "Non viene inviato nulla finché non tocchi Invia — qui o in Gmail.",
  "No email app on this phone — copy the email instead.": "Nessuna app email su questo telefono — copia invece l'email.",
  "Keep my messages and notifications forever": "Conserva per sempre i miei messaggi e le notifiche",
  "WhatsApp, SMS, email, deliveries, banks — so you can find what someone sent, years later. Never one-time codes. Backed up with Attune's backup (Backup & restore).": "WhatsApp, SMS, email, consegne, banche — così puoi trovare ciò che qualcuno ha mandato, anche anni dopo. Mai codici monouso. Salvati con il backup di Attune (Backup e ripristino).",
  "{n} kept.": "{n} conservati.",
  "New notifications are not kept now — the ones kept stay": "Le nuove notifiche ora non vengono conservate — quelle già conservate restano",
  "Tap again to forget all {n} — this can't be undone": "Tocca di nuovo per dimenticarle tutte e {n} — non si può annullare",
  "Forget everything kept": "Dimentica tutto ciò che è conservato",
  "Backed up": "Backup eseguito",
  "Google Drive · {f}": "Google Drive · {f}",
  "This phone · {f}": "Questo telefono · {f}",
  "Backs up by itself every day": "Fa il backup da solo ogni giorno",
  "Back up by itself every day": "Fai il backup da solo ogni giorno",
  "To {w}. Last: {t}. Everything, with Recall's messages, locked with your backup password; the newest 3 are kept.": "Su {w}. Ultimo: {t}. Tutto, con i messaggi di Ricordi, protetto dalla tua password di backup; vengono tenuti i 3 più recenti.",
  "Like WhatsApp: pick a folder once — on this phone (offline) or in Google Drive (online) — and Attune saves a locked backup there every day, messages included.": "Come WhatsApp: scegli una cartella una volta — su questo telefono (offline) o in Google Drive (online) — e Attune ci salva ogni giorno un backup protetto, messaggi inclusi.",
  "Backup password (8+ characters)": "Password di backup (8+ caratteri)",
  "You need this password to restore — write it down. It stays on this phone.": "Ti serve questa password per ripristinare — scrivila da qualche parte. Resta su questo telefono.",
  "Save the password": "Salva la password",
  "Change the folder": "Cambia cartella",
  "Choose the backup folder": "Scegli la cartella di backup",
  "Backing up…": "Backup in corso…",
  "Back up now": "Esegui il backup ora",
  "For Google Drive: in the picker tap ☰ → Drive → a folder (make one called Attune) → Use this folder.": "Per Google Drive: nel selettore tocca ☰ → Drive → una cartella (creane una chiamata Attune) → Usa questa cartella.",
  "Set a backup password first": "Imposta prima una password di backup",
