  "WhatsApp groups": "Gruppi WhatsApp",
  "Your groups sorted into albums with their photos — design, news, Hadith… (Chat X-Ray inside)": "I tuoi gruppi ordinati in album con le loro foto — design, notizie, Hadith… (dentro c'è la radiografia della chat)",
  "Reading the chat…": "Leggo la chat…",
