  "Album": "Album",
  "Let Attune sort it": "Lascia che Attune li ordini",
  "Couldn't read that file — pick the .xml the SMS backup app made.": "Impossibile leggere quel file — scegli il .xml creato dall'app di backup SMS.",
  "No bank or wallet messages from the last year in that file.": "Nessun messaggio di banche o portafogli dell'ultimo anno in quel file.",
  "From Google Play, install a free SMS backup app — e.g. “SMS Backup & Restore”.": "Da Google Play, installa un'app gratuita di backup SMS — es. “SMS Backup & Restore”.",
  "Open it → Back up → only Messages → save on this phone (Downloads).": "Aprila → Backup → solo Messaggi → salva su questo telefono (Download).",
  "Come back here and pick the backup file (.xml).": "Torna qui e scegli il file di backup (.xml).",
  "Pick the SMS backup file": "Scegli il file di backup SMS",
  "How?": "Come?",
  "Attune doesn't ask for SMS access (Google blocks apps installed from a file that do) — it reads the backup file instead.": "Attune non chiede l'accesso agli SMS (Google blocca le app installate da file che lo fanno) — legge invece il file di backup.",
  "Nothing had all your words — the closest:": "Niente conteneva tutte le tue parole — i più vicini:",
  "Nothing to search yet — add screenshots or keep your notifications below": "Ancora niente da cercare — aggiungi screenshot o conserva le notifiche qui sotto",
  "Add screenshots and photos": "Aggiungi screenshot e foto",
  "Their text is read on the phone, so “the receipt from Carrefour” finds them. They are kept in Mind.": "Il loro testo viene letto sul telefono, così “la ricevuta del Carrefour” li trova. Sono conservati in Mente.",
  "Keep my notifications for 30 days": "Conserva le mie notifiche per 30 giorni",
  "WhatsApp, SMS, email, deliveries, banks — so you can find what someone sent. Never one-time codes. Turning it off forgets them.": "WhatsApp, SMS, email, consegne, banche — così puoi trovare ciò che qualcuno ha mandato. Mai codici monouso. Disattivarlo le dimentica.",
  "Needs Notification access (the same switch as Money).": "Serve l'Accesso alle notifiche (lo stesso interruttore di Soldi).",
  "Everything stays on this phone.": "Tutto resta su questo telefono.",
