  "No price found online": "Nessun prezzo trovato online",
  "One result so far — the next report shows the trend.": "Finora un solo risultato — il prossimo referto mostrerà l'andamento.",
  "{n} results in {y} years: {a} → {b} {u} ({c}).": "{n} risultati in {y} anni: {a} → {b} {u} ({c}).",
