  "Show this to your doctor — the trend says more than one result.": "Mostralo al tuo medico — l'andamento dice più di un singolo risultato.",
  "Your watch's temperature rose {r} °C: ovulation around {o}, so the period is expected {n}.": "La temperatura del tuo orologio è salita di {r} °C: ovulazione intorno al {o}, quindi il ciclo è previsto {n}.",
  "(your own {d} days after ovulation)": "(i tuoi {d} giorni dopo l'ovulazione)",
  "(14 days after ovulation until 2 cycles are measured)": "(14 giorni dopo l'ovulazione finché non vengono misurati 2 cicli)",
  "No temperature rise yet — ovulation looks later than usual, so the period will likely be later than the date above.": "Nessun aumento di temperatura ancora — l'ovulazione sembra più tardi del solito, quindi il ciclo probabilmente arriverà dopo la data qui sopra.",
  "{n} nights of temperature from your watch — the rise after ovulation shows here.": "{n} notti di temperatura dal tuo orologio — qui compare l'aumento dopo l'ovulazione.",
  "A watch that measures night temperature (Galaxy Watch, Pixel Watch, Oura…) makes the prediction more exact.": "Un orologio che misura la temperatura notturna (Galaxy Watch, Pixel Watch, Oura…) rende la previsione più precisa.",
  "Use my watch's temperature": "Usa la temperatura del mio orologio",
  "Read now": "Leggi ora",
