  "What changed since {d}?": "Cosa è cambiato dal {d}?",
  "Automations": "Automazioni",
  "Say what should happen — “when my salary arrives, put 20% in the car fund” — and it runs by itself": "Di' cosa deve succedere — “quando arriva lo stipendio, metti il 20% nel fondo auto” — e si esegue da solo",
  "Say what should happen": "Di' cosa deve succedere",
