  "I didn't get that as an automation. Try: When my salary arrives, put 20% in the car fund.": "Non l'ho capito come automazione. Prova: Quando arriva lo stipendio, metti il 20% nel fondo auto.",
  "Automation on — it runs on the phone, no AI needed": "Automazione attiva — funziona sul telefono, senza bisogno di AI",
  "Turn it on": "Attivala",
