  "One page {c} can open on any phone: what they owe, their invoices, payments and job orders. No costs, no other client. Send it on WhatsApp or by email.": "Una pagina che {c} può aprire su qualsiasi telefono: quanto deve, le sue fatture, i pagamenti e gli ordini di lavoro. Niente costi, nessun altro cliente. Inviala su WhatsApp o per email.",
