  "Your phone's own offline speech recogniser listens to the video, piece by piece — the sound never leaves the phone. About as long as the video.": "Il riconoscimento vocale offline del tuo telefono ascolta il video, pezzo per pezzo — l'audio non lascia mai il telefono. Ci vuole circa quanto dura il video.",
  "Subtitles need Android 13 or newer": "I sottotitoli richiedono Android 13 o successivo",
  "Google sync on the computer needs one setup step by Attune's owner (its Google client) — use Wi-Fi with your phone until then.": "La sincronizzazione Google sul computer richiede un passaggio di configurazione da parte del proprietario di Attune (il suo client Google) — fino ad allora usa il Wi-Fi con il telefono.",
  "The first time, Google's sign-in page opens in your browser; after that the computer stays signed in.": "La prima volta si apre nel browser la pagina di accesso di Google; dopo, il computer resta collegato.",
  "Built from the \"{k}\" template in a second — change anything you like": "Creato dal modello \"{k}\" in un secondo — cambia quello che vuoi",
  "Android is downloading the offline speech pack for this language — try again when it finishes": "Android sta scaricando il pacchetto vocale offline per questa lingua — riprova quando ha finito",
  "That language isn't installed for offline voice — add it in the phone's Settings → Google → Speech → Offline languages": "Questa lingua non è installata per la voce offline — aggiungila in Impostazioni del telefono → Google → Voce → Lingue offline",
