  "Say “Ya Attune” to start": "Di' “Ya Attune” per iniziare",
  "The phone listens for «يا أتيون» or “Hey Attune” and opens this screen. On this phone only — nothing is recorded or sent. A notification shows while it listens.": "Il telefono ascolta «يا أتيون» o “Hey Attune” e apre questa schermata. Solo su questo telefono — niente viene registrato o inviato. Mentre ascolta compare una notifica.",
