  "Forgotten — any voice wakes it now.": "Dimenticata — ora lo attiva qualsiasi voce.",
  "Talk to Attune": "Parla con Attune",
  "Your details — bookings and better answers": "I tuoi dati — prenotazioni e risposte migliori",
  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "Privato: tutto qui resta su questo telefono — Attune non lo carica mai e la sua IA gira sul telefono. Risposte e agenti usano solo i dati di viaggio e di vita quotidiana (mai passaporto, telefono o email). Un sito di prenotazione riceve nome, passaporto e telefono solo quando tocchi “Compila i miei dati”.",
  "Use my details to make answers and agents fit me": "Usa i miei dati per adattare risposte e agenti a me",
  "Trips and hotels": "Viaggi e hotel",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "Gli agenti li usano quando la tua frase non lo dice — es. un hotel seguito cerca da solo le tue stelle.",
  "Daily life": "Vita quotidiana",
  "So Chat's answers fit you: food, health, your car, your work.": "Perché le risposte della Chat ti si adattino: cibo, salute, la tua auto, il tuo lavoro.",
  "For booking forms": "Per i moduli di prenotazione",
