  "The people, places and things in your life. Attune links everything about each one — payments, notes, messages, follow-ups — and Chat answers from it. Two with the same name? It asks which one.": "Le persone, i luoghi e le cose della tua vita. Attune collega tutto di ognuno — pagamenti, note, messaggi, cose da seguire — e la Chat risponde da lì. Due con lo stesso nome? Chiede quale.",
