  "With more than one model installed: quick questions use the one already running; code, maths, reasoning and long reports move to your strongest model that runs smoothly here, and photos to one that sees. A switch takes 10–30 s.": "Con più modelli installati: le domande rapide usano quello già attivo; codice, matematica, ragionamento e report lunghi passano al modello più forte che qui gira fluido, e le foto a uno che vede. Il cambio richiede 10–30 s.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \\\"nothing leaves this phone\\\".": "Il modello in sé non usa mai la rete. Il registro elenca ogni connessione che l'app ha fatto o rifiutato, solo host e motivo — la prova dietro \\\"niente lascia questo telefono\\\".",
