  "Ask for a normal deposit or a bank guarantee instead, and never sign anything blank.": "Chiedi invece una cauzione normale o una garanzia bancaria, e non firmare mai niente in bianco.",
  "It renews by itself — you keep paying unless you cancel in time.": "Si rinnova da solo — continui a pagare se non disdici in tempo.",
  "Ask for renewal only by written agreement, or put the cancel-by date in your Deadline Radar.": "Chiedi il rinnovo solo con accordo scritto, o metti la data per disdire nel tuo Radar scadenze.",
  "Only one side can end it, or it can be ended without notice.": "Solo una parte può recedere, o si può recedere senza preavviso.",
  "Ask that both sides can end it, with the same written notice (e.g. 30 days).": "Chiedi che entrambe le parti possano recedere, con lo stesso preavviso scritto (es. 30 giorni).",
  "The other side can change the terms or the price on its own.": "L'altra parte può cambiare condizioni o prezzo da sola.",
  "Ask that changes need both signatures, and that you can leave without a penalty if you don't accept them.": "Chiedi che le modifiche richiedano entrambe le firme e che tu possa uscire senza penale se non le accetti.",
  "A penalty or forfeit clause — check the amount and that it applies to both sides.": "Una clausola penale o di decadenza — controlla l'importo e che valga per entrambe le parti.",
  "Ask for a cap (e.g. one month's value) and the same penalty for the other side.": "Chiedi un tetto (es. il valore di un mese) e la stessa penale per l'altra parte.",
  "Money you pay here does not come back, even if the deal falls through.": "I soldi che paghi qui non tornano indietro, anche se l'affare salta.",
  "Ask that it is refunded if the other side cancels or doesn't deliver.": "Chiedi che vengano rimborsati se l'altra parte annulla o non consegna.",
  "You carry all the risk, with no limit.": "Tutto il rischio è tuo, senza limiti.",
  "Ask for a limit (e.g. the contract's value) and to exclude what you can't control.": "Chiedi un limite (es. il valore del contratto) e di escludere ciò che non puoi controllare.",
  "You may not work for a competitor after you leave — check how long and where.": "Non puoi lavorare per un concorrente dopo l'uscita — controlla per quanto e dove.",
  "Ask for 6–12 months at most, one city or field, and pay for the time it applies.": "Chiedi al massimo 6–12 mesi, una città o un settore, e un compenso per il periodo.",
  "Everything you make — even in your own time — would belong to them.": "Tutto ciò che crei — anche nel tuo tempo libero — sarebbe loro.",
  "Ask to limit it to work done for them, in work time, with their tools.": "Chiedi di limitarlo al lavoro fatto per loro, in orario di lavoro, con i loro strumenti.",
  "Disputes go to arbitration or to another country's courts — this can be slow and expensive for you.": "Le controversie vanno in arbitrato o ai tribunali di un altro paese — può essere lento e costoso per te.",
  "Ask for the courts of your own city.": "Chiedi i tribunali della tua città.",
  "You give up a right (to sue, to a refund, to object).": "Rinunci a un diritto (fare causa, a un rimborso, a opporti).",
  "Ask to delete the waiver.": "Chiedi di eliminare la rinuncia.",
  "Sold as it is, with no guarantee — problems found later are yours.": "Venduto così com'è, senza garanzia — i problemi scoperti dopo sono tuoi.",
  "Inspect it first (with an expert), or ask for a written guarantee period.": "Prima ispezionalo (con un esperto) o chiedi un periodo di garanzia scritto.",
  "Secrecy that never ends.": "Riservatezza senza fine.",
  "Ask for a fixed number of years (2–5 is common).": "Chiedi un numero fisso di anni (2–5 è comune).",
  "They may take money from your salary — check when and how much.": "Possono trattenere soldi dallo stipendio — controlla quando e quanto.",
  "Ask that deductions are only for set reasons, with a written notice and a cap.": "Chiedi che le trattenute siano solo per motivi stabiliti, con preavviso scritto e un tetto.",
  "Ask for no more than about 1–2 % a month, and a few days' grace.": "Chiedi non più di circa l'1–2 % al mese e qualche giorno di tolleranza.",
  "Ask for 5–10 % a year, written as a fixed schedule.": "Chiedi il 5–10 % all'anno, scritto come piano fisso.",
