  "Explain what you mean, e.g. “the price is 38,000 cash; 12,400 is the down payment”": "Spiega cosa intendi, es. “il prezzo è 38.000 in contanti; 12.400 è l'anticipo”",
  "Read the offer again with this": "Rileggi l'offerta con questo",
  "They want money before you see or receive it.": "Vogliono soldi prima che tu lo veda o lo riceva.",
  "Payment to a personal wallet or gift card — very hard to get back.": "Pagamento su un portafoglio personale o con una gift card — molto difficile da recuperare.",
  "They ask for a code sent to your phone — that is how accounts and wallets are stolen.": "Chiedono un codice inviato al tuo telefono — è così che si rubano account e portafogli.",
