  "Can I see it and pay on delivery (cash / card on receipt)?": "Posso vederlo e pagare alla consegna (contanti / carta al ricevimento)?",
  "What is the exact brand and model number? Can you send a photo of the label?": "Qual è esattamente il marchio e il numero di modello? Puoi mandare una foto dell'etichetta?",
  "Is there an official warranty, and for how long? Invoice included?": "C'è una garanzia ufficiale, e di quanto? Fattura inclusa?",
  "Can you do a better price? Others sell it for less.": "Puoi fare un prezzo migliore? Altri lo vendono a meno.",
  "What is the total I pay, all fees included? Is there an early-payment penalty?": "Qual è il totale che pago, tutte le commissioni incluse? C'è una penale per il pagamento anticipato?",
