  "US Navy method: waist at the navel (women: narrowest), neck below the Adam's apple — ±3 %. The trend matters more than one number.": "Metodo US Navy: vita all'ombelico (donne: punto più stretto), collo sotto il pomo d'Adamo — ±3 %. Conta più l'andamento che un singolo numero.",
