  "Stopped — what was downloaded is kept": "Interrotto — ciò che è stato scaricato resta",
  "The offline food pack is ready": "Il pacchetto alimenti offline è pronto",
  "Delete the offline food pack from this phone?": "Eliminare il pacchetto alimenti offline da questo telefono?",
  "Offline food pack": "Pacchetto alimenti offline",
  "Over a million packaged foods from Open Food Facts — Egyptian and Arab products first. Search by name or barcode with no signal.": "Oltre un milione di alimenti confezionati da Open Food Facts — prima i prodotti egiziani e arabi. Cerca per nome o codice a barre senza segnale.",
  "Get Egypt + most popular (~240,000, ~30 MB)": "Scarica Egitto + i più popolari (~240.000, ~30 MB)",
  "Get everything (1,000,000+)": "Scarica tutto (1.000.000+)",
  "Photo recognition is ready — a food photo now takes about a second": "Il riconoscimento foto è pronto — ora una foto di cibo richiede circa un secondo",
  "Delete the photo recognition model from this phone?": "Eliminare il modello di riconoscimento foto da questo telefono?",
  "Fast photo recognition": "Riconoscimento foto rapido",
  "Two picture models (~200 MB, once) that name the food in a photo in a few seconds — your country's dishes first — offline. They learn from the photo meals you save.": "Due modelli d'immagine (~200 MB, una volta) che riconoscono il cibo in una foto in pochi secondi — prima i piatti del tuo paese — offline. Imparano dai pasti fotografati che salvi.",
  " MB": " MB",
  "Get it (~100 MB)": "Scaricalo (~100 MB)",
  "Health Sync is installed ✓": "Health Sync è installato ✓",
  "Install Health Sync (free trial, then a small one-time payment to its maker — not to us).": "Installa Health Sync (prova gratuita, poi un piccolo pagamento una tantum al suo sviluppatore — non a noi).",
  "Open Health Sync": "Apri Health Sync",
  "Get Health Sync": "Prendi Health Sync",
  "In Health Sync: source = Huawei Health → sign in with your Huawei ID and allow it.": "In Health Sync: origine = Huawei Health → accedi con il tuo Huawei ID e consenti.",
  "Destination = Health Connect → allow steps, calories, distance, heart rate and exercise.": "Destinazione = Health Connect → consenti passi, calorie, distanza, battito e allenamenti.",
  "Back here: “Connect my watch”, then Refresh. The first sync can take a few minutes.": "Torna qui: “Collega il mio orologio”, poi Aggiorna. La prima sincronizzazione può richiedere qualche minuto.",
  "Huawei watch: Huawei Health doesn't share with Android's Health Connect by itself — the app Health Sync copies it across (once, then automatically).": "Orologio Huawei: Huawei Health non condivide da solo con Health Connect di Android — l'app Health Sync copia i dati (una volta, poi in automatico).",
  "Open Huawei Health (let it sync the watch first)": "Apri Huawei Health (lascia che sincronizzi prima l'orologio)",
  "Huawei Health sent nothing — open Huawei Health once so the watch syncs, and check Attune is still allowed in Huawei Health → Me → Privacy → Data sharing.": "Huawei Health non ha inviato niente — apri Huawei Health una volta perché l'orologio si sincronizzi, e controlla che Attune sia ancora consentito in Huawei Health → Io → Privacy → Condivisione dati.",
  "Huawei Health wasn't allowed — tap Connect again and allow steps, calories, distance and heart rate.": "Huawei Health non è stato consentito — tocca di nuovo Collega e consenti passi, calorie, distanza e battito.",
  "Watch steps and calories work in the Android app.": "Passi e calorie dell'orologio funzionano nell'app Android.",
  "Huawei watch or band: connect Huawei Health directly — steps, calories, distance and heart rate, read only.": "Orologio o braccialetto Huawei: collega Huawei Health direttamente — passi, calorie, distanza e battito, sola lettura.",
  "Connect Huawei Health": "Collega Huawei Health",
  "First install HMS Core (Huawei's services — free)": "Installa prima HMS Core (servizi Huawei — gratis)",
  "Connect your watch: steps, calories burned, workouts and heart rate go into your day automatically.": "Collega l'orologio: passi, calorie bruciate, allenamenti e battito entrano da soli nella tua giornata.",
  "Through Android's Health Connect — works with Samsung Health (Galaxy Watch), Fitbit / Pixel Watch, Garmin Connect, Mi Fitness, Huawei Health (through Health Sync) and others that share to it. Read only; nothing leaves the phone.": "Tramite Health Connect di Android — funziona con Samsung Health (Galaxy Watch), Fitbit / Pixel Watch, Garmin Connect, Mi Fitness, Huawei Health (tramite Health Sync) e altri che condividono lì. Sola lettura; niente lascia il telefono.",
  "Huawei watch?": "Orologio Huawei?",
  "This phone doesn't have Health Connect — install it from the Play Store (Android 9–13), or it's built into Settings on Android 14+. Phones without Google services (newer Huawei phones) can't use it.": "Questo telefono non ha Health Connect — installalo dal Play Store (Android 9–13), oppure è integrato nelle Impostazioni da Android 14. I telefoni senza servizi Google (i Huawei più recenti) non possono usarlo.",
  "Install Health Connect": "Installa Health Connect",
  "Connect my watch": "Collega il mio orologio",
  "Huawei Health, through Health Sync ✓": "Huawei Health, tramite Health Sync ✓",
  "active kcal": "kcal attive",
  "≈ worked out from your steps — your watch app didn't send its calories / distance. In Health Sync, switch on Calories and Distance too.": "≈ calcolato dai passi — l'app dell'orologio non ha inviato calorie / distanza. In Health Sync attiva anche Calorie e Distanza.",
  "Latest from the watch: ": "Ultimo dato dall'orologio: ",
  " — open Huawei Health / Health Sync so it sends the newest steps": " — apri Huawei Health / Health Sync perché invii i passi più recenti",
  "Workout": "Allenamento",
  "Burned calories count the watch or your logged workouts — whichever is more, never both.": "Le calorie bruciate contano l'orologio o gli allenamenti registrati — il valore più alto, mai entrambi.",
  "Nothing from the watch today yet — open its app once so it syncs.": "Ancora niente dall'orologio oggi — apri la sua app una volta perché si sincronizzi.",
  "Matched to your watch": "Allineato al tuo orologio",
  " kcal / 1,000 steps": " kcal / 1.000 passi",
  " m a step": " m a passo",
  "Match again": "Allinea di nuovo",
  "Numbers lower than your watch? Match it": "Numeri più bassi del tuo orologio? Allinea",
  "Look at your watch now and type what it shows — Attune will count like your watch from now on.": "Guarda ora l'orologio e scrivi cosa mostra — da ora Attune conterà come il tuo orologio.",
  "kcal (Heat / Active)": "kcal (Calore / Attive)",
