  "Which messages to read": "Quali messaggi leggere",
  "Tell Attune whose message you are waiting for — on WhatsApp, Gmail, SMS or any email app — and it tells you the moment it arrives. Checked on this phone; SMS can be switched off below.": "Di' ad Attune da chi aspetti un messaggio — su WhatsApp, Gmail, SMS o qualsiasi app email — e ti avvisa appena arriva. Controllato su questo telefono; gli SMS si possono disattivare qui sotto.",
  "Numbers in the photo, read by the phone: {n} — check them.": "Numeri nella foto, letti dal telefono: {n} — controllali.",
  "Was due {d}": "Scadeva il {d}",
  "Due {d} · in {n} days": "Scade il {d} · tra {n} giorni",
  "Due date (optional)": "Scadenza (facoltativa)",
  "What it should always know about this work": "Cosa deve sapere sempre di questo lavoro",
  "Delete this project? Its chats stay in Chat.": "Eliminare questo progetto? Le sue chat restano in Chat.",
  "Pages, documents and programs Attune made in this work. Ask for one, then tap Save on its card — it is kept here.": "Pagine, documenti e programmi creati da Attune in questo lavoro. Chiedine uno, poi tocca Salva sulla sua scheda: resta qui.",
  "Nothing saved here yet.": "Qui non c'è ancora niente di salvato.",
  "Questions this work asks again and again. Run one with a tap — the ones whose time has come are marked.": "Domande che questo lavoro fa ancora e ancora. Avviane una con un tocco: quelle arrivate al momento sono segnate.",
  "No repeats yet.": "Ancora nessuna ripetizione.",
