  "Due now": "È il momento",
  "e.g. What is still open, and what is due this week?": "es. Cosa è ancora aperto e cosa scade questa settimana?",
  "Add a repeat": "Aggiungi una ripetizione",
  "Just Attune": "Solo Attune",
  "No special role": "Nessun ruolo speciale",
