  "Answers as": "Risponde come",
  "Earlier chats": "Chat precedenti",
  "Saved to this work": "Salvato in questo lavoro",
  "Saved items": "Salvati",
  "Close this Zakāt year? Its payments become one closed year with a certificate, and a new Zakāt year starts today.": "Chiudere questo anno di Zakāt? I suoi pagamenti diventano un anno chiuso con certificato, e oggi inizia un nuovo anno di Zakāt.",
  "Closed — the certificate is under Closed years": "Chiuso — il certificato è in Anni chiusi",
  "Ramadan is here — Zakāt al-Fiṭr is due before the Eid prayer": "È Ramadan — la Zakāt al-Fiṭr va data prima della preghiera dell'Eid",
  "One question before your Zakāt is worked out": "Una domanda prima di calcolare la tua Zakāt",
  "You owe {a}. Scholars differ on whether a debt is taken off the wealth you pay Zakāt on. It is your choice — until you choose, nothing is taken off.": "Devi {a}. I sapienti divergono sul togliere un debito dal patrimonio su cui paghi la Zakāt. Scegli tu — finché non scegli, non si toglie nulla.",
  "Below the niṣāb": "Sotto il niṣāb",
  "due {d}": "scade {d}",
  "Zakāt {a} · 2.5% of {b}": "Zakāt {a} · 2,5% di {b}",
  "Niṣāb {a}": "Niṣāb {a}",
  "{n} g of {m} g": "{n} g su {m} g",
  "Livestock Zakāt": "Zakāt del bestiame",
  "{n} head": "{n} capi",
  "Not free-grazing — no Zakāt on them": "Non al pascolo libero — niente Zakāt",
  "Below the niṣāb ({n} head)": "Sotto il niṣāb ({n} capi)",
  "Due now: {x}": "Dovuta ora: {x}",
  "Its ḥawl is running — due {d} (in {n} days)": "Il suo ḥawl è in corso — scade {d} (tra {n} giorni)",
  "Paid vs due": "Pagato e dovuto",
  "Paid so far": "Pagato finora",
  "Still to pay": "Ancora da pagare",
  "Fully paid — may Allah accept it": "Pagata tutta — che Allah l'accetti",
  "Close this Zakāt year": "Chiudi questo anno di Zakāt",
  "Closed years": "Anni chiusi",
  "No closed year yet — when you finish paying a year's Zakāt, close it here and keep its certificate.": "Nessun anno chiuso — quando finisci di pagare la Zakāt di un anno, chiudilo qui e tieni il certificato.",
  "An estimate to guide you. It uses the gold nisab (85g) and 2.5% on cash, gold, silver and money owed to you — not your home, car, or work equipment. Rulings on debts and on dropping below nisab during the year differ between scholars; confirm your case with a trusted scholar.": "Una stima per orientarti. Usa il niṣāb dell'oro (85 g) e il 2,5% su contanti, oro, argento e soldi che ti devono — non sulla casa, l'auto o l'attrezzatura di lavoro. Le regole sui debiti e sullo scendere sotto il niṣāb durante l'anno variano tra i sapienti; verifica il tuo caso con un sapiente di fiducia.",
  "Nothing yet today — tell the box what you spent or need to remember.": "Ancora niente oggi — di' alla casella cosa hai speso o cosa devi ricordare.",
  "These offers were read before Attune could read the hotel names and photos — tap Check now to get them.": "Queste offerte sono state lette prima che Attune sapesse leggere nomi e foto degli hotel — tocca Controlla ora per averli.",
