  "Help me run this renovation: compare quotes, keep the budget and the order of the work.": "Aiutami a gestire questa ristrutturazione: confronta i preventivi, rispetta il budget e l'ordine dei lavori.",
  "Get 3 quotes": "Chiedi 3 preventivi",
