  "“Make my travel checklist: passport, charger” — then “I'm travelling Thursday”": "«Fai la mia lista di viaggio: passaporto, caricatore» — poi «parto giovedì»",
  "On Wednesday the list is on Home, every box empty, until it is all ticked": "Mercoledì la lista è in Home, tutte le caselle vuote, finché non spunti tutto",
  "Read from the receipt: {a} — check it": "Letto dalla ricevuta: {a} — controlla",
  "Receipt added": "Ricevuta aggiunta",
  "Add a receipt": "Aggiungi una ricevuta",
  "Open the best offer": "Apri l'offerta migliore",
  "Open Scout": "Apri Scout",
  "See {n} new ads": "Vedi {n} nuovi annunci",
  "See the ads": "Vedi gli annunci",
  "Open the alerts": "Apri gli avvisi",
  "The 3→ع Franco chip: type Franco (“ana gay bokra”) and each word turns Arabic («أنا جاي بكرة») when you press space.": "Il chip Franco 3→ع: scrivi in Franco («ana gay bokra») e ogni parola diventa araba («أنا جاي بكرة») quando premi spazio.",
  "Say what should happen, in one sentence: “When my salary arrives, put 20% in the car fund”, «لما المرتب ينزل حط 20% في صندوق العربية».": "Di' cosa deve succedere, in una frase: «Quando arriva lo stipendio, metti il 20% nel fondo auto», «لما المرتب ينزل حط 20% في صندوق العربية».",
  "Type what you remember, the way you'd say it: “the wifi password from a screenshot”, «العنوان اللي أحمد بعته على الواتس», “the Carrefour receipt in March”.": "Scrivi quello che ricordi, come lo diresti: «la password del wifi da uno screenshot», «العنوان اللي أحمد بعته على الواتس», «lo scontrino Carrefour di marzo».",
  "Recall looks through your screenshots, the notifications you kept, your chats, Mind, saved pages and payments — and understands dates, apps and words that mean the same (receipt = فاتورة).": "Ricorda cerca tra i tuoi screenshot, le notifiche conservate, le chat, Mind, le pagine salvate e i pagamenti — e capisce date, app e parole con lo stesso significato (scontrino = فاتورة).",
  "Type a goal with a number and a date: «عايز أوفر 60 ألف قبل يونيو», “lose 6 kg before 20 January”, a Corolla 2022 under 900,000 before 1 December. Tap Start the mission. More kinds: a spending limit («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده»), a debt from Money → People («عايز أخلص دين أحمد قبل ديسمبر»), a Learn course (“finish the Turkish course by December”), and for a company that uses Business → Fleet & rentals: “collect 200k from clients by the end of the month”.": "Scrivi un obiettivo con un numero e una data: «عايز أوفر 60 ألف قبل يونيو», «perdere 6 kg entro il 20 gennaio», una Corolla 2022 sotto 900.000 entro il 1° dicembre. Tocca Avvia la missione. Altri tipi: un limite di spesa («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده»), un debito da Soldi → Persone («عايز أخلص دين أحمد قبل ديسمبر»), un corso di Impara («finire il corso di turco entro dicembre») e, per un'azienda che usa Business → Flotta e noleggi: «incassare 200 mila dai clienti entro fine mese».",
  "Ask “total of the amount column” or «إجمالي المبلغ» — the PDF's tables are added up by code, exactly; “Tables → Excel” saves them all.": "Chiedi «totale della colonna importo» o «إجمالي المبلغ» — le tabelle del PDF vengono sommate dal codice, esattamente; «Tabelle → Excel» le salva tutte.",
  "Message alerts: type “tell me when Ahmed messages me” or «لو جالي إيميل من البنك قولي» on Home — Attune tells you the moment it arrives (WhatsApp, Gmail, any email app).": "Avvisi messaggi: scrivi «avvisami quando Ahmed mi scrive» o «لو جالي إيميل من البنك قولي» nella Home — Attune ti avvisa appena arriva (WhatsApp, Gmail, qualsiasi app di posta).",
  "Search all your groups at the top («كنبة رمادي», “gold price”); tap a photo to move it to another album; export again any time — only what's new is added.": "Cerca in tutti i tuoi gruppi in alto («كنبة رمادي», «prezzo dell'oro»); tocca una foto per spostarla in un altro album; esporta di nuovo quando vuoi — si aggiunge solo il nuovo.",
  "Say it in the Home box too: «خطة الشهر», “save 20000 for travel by June”.": "Dillo anche nella casella della Home: «خطة الشهر», «risparmiare 20000 per il viaggio entro giugno».",
  "Open To-dos & lists (in the menu, under My life) and tap New list: a name, the items one per line, then Does it repeat? — No, every day, every week (pick the days), every month, or before a date (a trip).": "Apri Cose da fare e liste (nel menu, sotto La mia vita) e tocca Nuova lista: un nome, le voci una per riga, poi Si ripete? — No, ogni giorno, ogni settimana (scegli i giorni), ogni mese o prima di una data (un viaggio).",
  "Or just say it in the box on Home: «make my travel checklist: passport, charger, medicines», «every Saturday: clean the flat, pay the maid», «I'm travelling Thursday».": "Oppure dillo nella casella della Home: «fai la mia lista per il viaggio: passaporto, caricatore, medicine», «ogni sabato: pulire casa, pagare la colf», «parto giovedì».",
  "On its day the list is on Home with every box empty; tick there. What is late or not finished stays on Home until you tick it.": "Nel suo giorno la lista è nella Home con tutte le caselle vuote; spunta lì. Ciò che è in ritardo o non finito resta nella Home finché non lo spunti.",
  "A list for a trip? Say the day you travel, and it comes up the days before with every box empty.": "Una lista per un viaggio? Di' il giorno in cui parti: comparirà nei giorni prima con tutte le caselle vuote.",
  "Saved → People → Add: write what YOU call them (“Ahmed the plumber”, «الحلاق»), who they are to you, and link their phone contact if you like.": "Salvati → Persone → Aggiungi: scrivi come le chiami TU («Ahmed l'idraulico», «الحلاق»), chi sono per te e, se vuoi, collega il loro contatto del telefono.",
  "Ask Chat about it any time: “what happens in chapter 3?”, «الخبر ده بيقول إيه عن الدولار؟». The answer comes from your own copy.": "Chiedi alla Chat quando vuoi: «cosa succede nel capitolo 3?», «الخبر ده بيقول إيه عن الدولار؟». La risposta viene dalla tua copia.",
  "Fleet & rentals → From a message: paste or share a client's WhatsApp («محتاج ونش 50 طن السبت في 6 أكتوبر يومين»). It reads the tons, the day, days or hours and the site (6 October is the city), and lists the cranes free those days — smallest that fits first; booked ones show their job.": "Flotta e noleggi → Da un messaggio: incolla o condividi il WhatsApp di un cliente («محتاج ونش 50 طن السبت في 6 أكتوبر يومين»). Legge le tonnellate, il giorno, i giorni o le ore e il cantiere (6 Ottobre è la città) ed elenca le gru libere in quei giorni — prima la più piccola adatta; quelle prenotate mostrano il loro lavoro.",
  "Search «كنبة رمادي»": "Cerca «كنبة رمادي»",
