  "Taken off the widget": "Tolta dal widget",
  "Pinned — add the “Attune · A list” widget to your home screen": "Fissata — aggiungi il widget «Attune · Una lista» alla schermata Home",
  "Take it off the widget": "Toglila dal widget",
