  "Sharing is set — send the first update": "Condivisione pronta — invia il primo aggiornamento",
  "Our Money in Attune — open it in Attune → Money → More → Share with family": "I nostri soldi in Attune — aprilo in Attune → Soldi → Altro → Condividi con la famiglia",
  "Update ready — {n} entries": "Aggiornamento pronto — {n} movimenti",
  "From {who}: {a} added · {c} changed · {r} removed": "Da {who}: {a} aggiunti · {c} cambiati · {r} tolti",
  "Share with family": "Condividi con la famiglia",
  "A file locked with a family code you agree on, sent through WhatsApp or any app. No account, no server — only the people with the code can open it.": "Un file bloccato con un codice di famiglia concordato, inviato su WhatsApp o qualsiasi app. Niente account, niente server — solo chi ha il codice può aprirlo.",
  "Sharing all of Money": "Condividi tutti i Soldi",
  "Sharing: {a}": "Condividi: {a}",
  "You are {me} · family code {c}": "Sei {me} · codice di famiglia {c}",
  "Send the update": "Invia l'aggiornamento",
  "Open an update I got": "Apri un aggiornamento ricevuto",
  "Stop sharing? What was shared stays in your Money.": "Smettere di condividere? Ciò che è stato condiviso resta nei tuoi Soldi.",
  "Stop sharing": "Smetti di condividere",
  "Start sharing": "Inizia a condividere",
  "Choose what to share, then send the first update": "Scegli cosa condividere, poi invia il primo aggiornamento",
  "Join a share": "Unisciti a una condivisione",
  "Open the file someone sent you, with your family code": "Apri il file che ti hanno mandato, con il codice di famiglia",
  "Some accounts (e.g. “House”)": "Alcuni conti (es. «Casa»)",
  "Only these are shared; everything else stays yours.": "Solo questi sono condivisi; il resto resta tuo.",
  "All of Money": "Tutti i Soldi",
  "Every account and entry, with one person you trust.": "Ogni conto e movimento, con una persona di cui ti fidi.",
  "Your name": "Il tuo nome",
  "Family code (6 letters or more, the same on both phones)": "Codice di famiglia (6 lettere o più, uguale sui due telefoni)",
  "Open the file": "Apri il file",
  "Attune reads the notifications your apps show (WhatsApp, SMS, email, Instagram, YouTube…) to plan your day: who wrote, what someone asked for at a time, what arrives today.": "Attune legge le notifiche delle tue app (WhatsApp, SMS, email, Instagram, YouTube…) per organizzare la giornata: chi ha scritto, cosa ti hanno chiesto per un orario, cosa arriva oggi.",
  "They are read and kept on this phone only. Nothing is sent to us or to anyone. No account, no cloud.": "Vengono lette e tenute solo su questo telefono. Niente viene inviato a noi o ad altri. Niente account, niente cloud.",
  "You choose which apps count (Settings → Your day), and you can forget everything kept at any time.": "Scegli tu quali app contano (Impostazioni → La tua giornata) e puoi cancellare tutto in qualsiasi momento.",
  "Is this a scam?": "È una truffa?",
  "Paste a message, an offer or a link — or pick a screenshot. Checked on this phone; nothing is sent anywhere.": "Incolla un messaggio, un'offerta o un link — o scegli uno screenshot. Controllato su questo telefono; niente viene inviato.",
  "e.g. “You won 5,000 EGP from InstaPay — send the code you'll receive…”": "es. «Hai vinto 5.000 EGP da InstaPay — invia il codice che riceverai…»",
  "No text found in the picture": "Nessun testo trovato nell'immagine",
  "Whatever it says: never share a code, a card number or a password.": "Qualunque cosa dica: non condividere mai un codice, un numero di carta o una password.",
  "no": "no",
  "send": "invia",
  "anyone": "chiunque",
  "Reminder set: {t}": "Promemoria impostato: {t}",
