  "The five prayers for your city, and a day planned around them. Off unless you want it.": "Le cinque preghiere della tua città e una giornata organizzata intorno. Spento a meno che tu non lo voglia.",
  "Ramadan mode": "Modalità Ramadan",
  "Only during Ramadan: the countdown to iftar on Home and a day planned around the fast.": "Solo durante il Ramadan: il conto alla rovescia per l'iftar in Home e una giornata intorno al digiuno.",
  "Use my notifications to plan my day": "Usa le mie notifiche per organizzare la giornata",
