  "medium": "media",
  "How many days is the trip? (e.g. 4 days)": "Quanti giorni dura il viaggio? (es. 4 giorni)",
  "remind me tomorrow at 9 to call the bank": "ricordami domani alle 9 di chiamare la banca",
