  "Be careful": "Attenzione",
  "No warning signs found": "Nessun segnale d'allarme trovato",
  "Safe to spend today: {a}": "Spendibile oggi: {a}",
  "Nothing due today — open Attune to add a to-do": "Niente in scadenza oggi — apri Attune per aggiungere una cosa da fare",
  "A list": "Una lista",
  "In Attune: To-dos & lists → open a list → Pin to the widget": "In Attune: Cose da fare e liste → apri una lista → Fissa sul widget",
  "Every box is ticked": "Tutte le caselle spuntate",
  "This update is from another share.": "Questo aggiornamento è di un'altra condivisione.",
  "The ledger didn't take it": "Il registro non l'ha accettato",
  "Open Money first": "Apri prima Soldi",
  "This isn't a Money share.": "Questo non è un file di Soldi condivisi.",
  "They want money before you see or receive anything.": "Vogliono soldi prima che tu veda o riceva qualcosa.",
  "Payment to a personal wallet or a gift card — very hard to get back.": "Pagamento su un portafoglio personale o una gift card — difficilissimo da recuperare.",
  "Guaranteed high profit — the sign of an investment scam.": "Profitto alto garantito — segno di truffa sugli investimenti.",
  "“Your account will be blocked” — banks and wallets never ask you to fix it through a message.": "«Il tuo conto verrà bloccato» — banche e portafogli non chiedono mai di sistemarlo via messaggio.",
  "They ask for your card number, PIN or password — never give these to anyone.": "Chiedono numero di carta, PIN o password — non darli mai a nessuno.",
  "“This is my new number” followed by a request — call the person on their old number first.": "«Questo è il mio nuovo numero» e poi una richiesta — chiama prima la persona al vecchio numero.",
  "A parcel “held” until you pay a small fee — a common trick to get your card details.": "Un pacco «trattenuto» finché non paghi una piccola tassa — trucco comune per prendere i dati della carta.",
  "Easy money for liking videos or small tasks — these end with you paying “to unlock” your earnings.": "Soldi facili mettendo like a video o piccoli compiti — finisce che paghi per «sbloccare» i guadagni.",
  "A link that asks you to log in or confirm something.": "Un link che ti chiede di accedere o confermare qualcosa.",
  "The link says “{b}” but goes to {l} — not the real site.": "Il link dice «{b}» ma porta a {l} — non è il sito vero.",
  "Your day from your notifications (optional)": "La tua giornata dalle notifiche (facoltativo)",
  "With Notification access on, Attune reads the notifications kept on the device to plan your day: who wrote to you today, what someone asked for at a time (shown as a reminder you can add), what arrives today, and a count of other apps (Instagram, YouTube…). This happens on the device, by code; nothing is sent anywhere. Choose which apps count, or switch it off, in Settings → Your day.": "Con l'accesso alle notifiche attivo, Attune legge le notifiche tenute sul dispositivo per organizzare la giornata: chi ti ha scritto oggi, cosa ti hanno chiesto per un orario (mostrato come promemoria da aggiungere), cosa arriva oggi e un conteggio delle altre app (Instagram, YouTube…). Avviene sul dispositivo, con il codice; nulla viene inviato da nessuna parte. Scegli quali app contano, o disattivalo, in Impostazioni → La tua giornata.",
  "Sharing Money with family (optional)": "Condividere i Soldi con la famiglia (facoltativo)",
  "If you start a family share, Attune makes one file with only what you chose (some accounts, or all of Money), locked with a family code you agree on (AES-256), and hands it to the app you pick (WhatsApp, email…) to send. Attune has no server and never sees it; only people with the code can open it. Zakat records are never shared. Stop any time in Money → More → Share with family.": "Se avvii una condivisione familiare, Attune crea un unico file solo con ciò che hai scelto (alcuni conti o tutti i Soldi), bloccato con un codice di famiglia concordato (AES-256), e lo passa all'app che scegli (WhatsApp, email…) per inviarlo. Attune non ha server e non lo vede mai; solo chi ha il codice può aprirlo. Le registrazioni di zakat non vengono mai condivise. Puoi smettere quando vuoi da Soldi → Altro → Condividi con la famiglia.",
