  "Birthdays, reminders to people, a message for later — once, or every day, week, month or year.": "Compleanni, promemoria alle persone, un messaggio per dopo — una volta, o ogni giorno, settimana, mese o anno.",
  "asks first": "chiede prima",
  "How messages are sent": "Come partono i messaggi",
  "Through the chat's own reply when its notification is on your phone; otherwise a notification opens the chat with the message written — one tap on Send.": "Con la risposta della chat stessa quando la sua notifica è sul telefono; altrimenti una notifica apre la chat con il messaggio scritto — un tocco su Invia.",
  "Send by itself is on (WhatsApp, phone unlocked).": "«Invia da solo» è attivo (WhatsApp, telefono sbloccato).",
  "Turn on “Send by itself” (like Auto Text)": "Attiva «Invia da solo» (come Auto Text)",
  "Allow SMS to be sent by itself": "Consenti l'invio automatico degli SMS",
  "What “Send by itself” does": "Cosa fa «Invia da solo»",
  "At a message's time, Attune opens that WhatsApp chat with your message written and presses Send for you.": "All'ora del messaggio, Attune apre quella chat WhatsApp con il messaggio scritto e preme Invia per te.",
  "It uses Android's Accessibility service only for that: only in WhatsApp, only for messages you scheduled, only when the box holds your message.": "Usa il servizio Accessibilità di Android solo per questo: solo in WhatsApp, solo per i messaggi che hai programmato, solo quando la casella contiene il tuo messaggio.",
  "It reads nothing else and sends nothing else. When the phone is locked it can't — you get the one-tap notification instead.": "Non legge e non invia nient'altro. Con il telefono bloccato non può — ricevi la notifica da un tocco.",
  "Open Accessibility settings": "Apri le impostazioni di Accessibilità",
  "In Settings: Accessibility → Attune → turn it on. Come back here after.": "In Impostazioni: Accessibilità → Attune → attivalo. Poi torna qui.",
  "Attune answers by itself through the chat's own reply — it needs Notification access, and works in every version.": "Attune risponde da solo con la risposta della chat — serve l'accesso alle notifiche e funziona in ogni versione.",
  "New rule": "Nuova regola",
  "Replied today": "Risposte di oggi",
  "Nothing sent yet. Scheduled messages and auto-replies show here once they go.": "Ancora niente inviato. I messaggi programmati e le risposte automatiche compaiono qui quando partono.",
  "Driving": "Alla guida",
  "I'm driving now — I'll call you when I arrive.": "Sto guidando — ti chiamo appena arrivo.",
  "In a meeting / praying": "In riunione / in preghiera",
  "I'm in a meeting — I'll answer you shortly.": "Sono in riunione — ti rispondo a breve.",
  "I'll answer you in the morning.": "Ti rispondo domattina.",
