  "Follow-ups → ⋯ → Errands. Type it once: “car licence expires 3 Feb 2027, plate أ ب ج 1234”.": "Promemoria → ⋯ → Pratiche. Scrivilo una volta: «il libretto scade il 3 feb 2027, targa أ ب ج 1234».",
  "Before it is due it shows under Needs you, with the papers to bring.": "Prima della scadenza compare in Ti serve, con i documenti da portare.",
  "Open the official page — Attune reads what is due; you press Pay.": "Apri la pagina ufficiale — Attune legge cosa è dovuto; paghi tu.",
  "Traffic fines, bills, licences, a crane's inspection — all in one list.": "Multe, bollette, patenti, l'ispezione di una gru — tutto in una lista.",
  "driving licence expires 20 Nov 2026": "la patente scade il 20 nov 2026",
  "Driving licence · in 13 days": "Patente · tra 13 giorni",
  "“Car licence expires 3 Feb 2027”": "«Il libretto scade il 3 feb 2027»",
  "Told before it is due, with the papers to bring": "Avviso prima della scadenza, con i documenti",
  "Each place is one page with tabs on top — Money opens on your money, with Follow-ups next to it.": "Ogni posto è una pagina con schede in alto — Soldi si apre sui tuoi soldi, con Promemoria accanto.",
  "Attune puts it in the right place — Money, Reminders, People & plans, To-dos, Dates — and says what it did. Wrong? Tap Undo.": "Attune lo mette al posto giusto — Soldi, Promemoria, Persone e impegni, Cose da fare, Date — e dice cosa ha fatto. Sbagliato? Tocca Annulla.",
  "One sentence does a lot: “Ahmed owes me 12,000, 1,000 a month” becomes 12 payments with a reminder before each one.": "Una frase fa tanto: «Ahmed mi deve 12.000, 1.000 al mese» diventa 12 rate con un promemoria prima di ognuna.",
  "Type a goal with a number and a date: «عايز أوفر 60 ألف قبل يونيو», “lose 6 kg before 20 January”, a Corolla 2022 under 900,000 before 1 December. Tap Start the mission. More kinds: a spending limit («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده») and a debt from Money → People («عايز أخلص دين أحمد قبل ديسمبر»).": "Scrivi un obiettivo con un numero e una data: «عايز أوفر 60 ألف قبل يونيو», «perdere 6 kg entro il 20 gennaio», una Corolla 2022 sotto 900.000 entro il 1° dicembre. Tocca Avvia la missione. Altri tipi: un limite di spesa («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده») e un debito da Soldi → Persone («عايز أخلص دين أحمد قبل ديسمبر»).",
  "Every time Attune opens it reads your Money and the prices your agents saw, and shows your real chance (from your own past days, thousands of possible futures) and your progress.": "Ogni volta che Attune si apre legge i tuoi Soldi e i prezzi visti dai tuoi agenti, e mostra la tua vera probabilità (dai tuoi giorni passati, migliaia di futuri possibili) e i progressi.",
  "Tools holds Writing, Files & Converter and Ask a PDF — tap one to open it.": "Strumenti contiene Scrittura, File e convertitore e Chiedi a un PDF — toccane uno per aprirlo.",
  "Paste once, then try another action on the same text.": "Incolla una volta, poi prova un'altra azione sullo stesso testo.",
  "Save it as:": "Salvala come:",
  "Or say how — “remind me Monday at 9”, “subscription 200 every month”": "Oppure di' come — «ricordami lunedì alle 9», «abbonamento 200 al mese»",
  "I couldn't read that — try “reminder tomorrow at 9” or “expense 450”": "Non ho capito — prova «promemoria domani alle 9» o «spesa 450»",
  "If your money stays as it is, you will pay about {a} on {d} ({p}% of {b}).": "Se i tuoi soldi restano così, pagherai circa {a} il {d} ({p}% di {b}).",
  "If your money stays as it is, it stays under the niṣāb — no Zakāt this year.": "Se i tuoi soldi restano così, resti sotto il niṣāb — niente Zakāt quest'anno.",
